import pandas as pd, statsmodels.formula.api as smf, numpy as np
df=pd.read_csv("data.csv");print(df.isna().sum().sum(), df.describe().T)
f="export_growth_2023~supplier_diversity"
for c in ["","+log_sales_2020+years_exporting_2020+export_growth_2020","+log_sales_2020+years_exporting_2020+export_growth_2020+inventory_days_2020+foreign_owned+share_imported_inputs_2020+port_distance_km+certified_iso+debt_ratio_2020+C(region)+listed+C(product_group)"]:
    r=smf.ols(f+c,df).fit(cov_type="HC1");print(r.params['supplier_diversity'],r.bse['supplier_diversity'])
for g in ['region','product_group','listed','foreign_owned','certified_iso']:
    for k,d in df.groupby(g):
        r=smf.ols(f+"+log_sales_2020+export_growth_2020",d).fit(cov_type="HC1");print(g,k,len(d),r.params['supplier_diversity'],r.pvalues['supplier_diversity'])
r=smf.ols(f+"+I(supplier_diversity**2)+log_sales_2020+export_growth_2020",df).fit(cov_type="HC1");print(r.summary().tables[1])
print(df.corr(numeric_only=True)['supplier_diversity'])
